package com.waykeep.app.util;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.Locale;

/**
 * Auto-generated track names (ISO/local timestamps) are stored as-is but shown as
 * "28 Oct 26" in the list. Custom names pass through untouched.
 */
public class TrackNameUtilsTest {

    private Locale defaultLocale;

    @Before
    public void setUp() {
        defaultLocale = Locale.getDefault();
        Locale.setDefault(Locale.ENGLISH);
    }

    @After
    public void tearDown() {
        Locale.setDefault(defaultLocale);
    }

    @Test
    public void isAutoGeneratedName_isoTimestamp() {
        OffsetDateTime start = OffsetDateTime.of(2026, 10, 28, 7, 13, 0, 0, ZoneOffset.of("+05:30"));
        assertTrue(TrackNameUtils.isAutoGeneratedName("2026-10-28T07:13+0530", start));
    }

    @Test
    public void isAutoGeneratedName_localTimestamp() {
        OffsetDateTime start = OffsetDateTime.of(2026, 10, 28, 7, 13, 0, 0, ZoneOffset.of("+05:30"));
        assertTrue(TrackNameUtils.isAutoGeneratedName(StringUtils.formatDateTimeWithOffset(start), start));
    }

    @Test
    public void isAutoGeneratedName_customName() {
        OffsetDateTime start = OffsetDateTime.of(2026, 10, 28, 7, 13, 0, 0, ZoneOffset.of("+05:30"));
        assertFalse(TrackNameUtils.isAutoGeneratedName("Evening Ride", start));
        assertFalse(TrackNameUtils.isAutoGeneratedName("Track 7", start));
        assertFalse(TrackNameUtils.isAutoGeneratedName(null, start));
    }

    @Test
    public void formatListDate_ddMmmYy() {
        OffsetDateTime start = OffsetDateTime.of(2026, 10, 28, 7, 13, 0, 0, ZoneOffset.of("+05:30"));
        assertEquals("28 Oct 26", TrackNameUtils.formatListDate(start));
    }
}
